import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReels() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Initialize Remix Icons if available
        if (window.RemixIcon) {
            window.RemixIcon.init();
        }
        
        // Load real data
        loadReels();
    }, []);

    const loadReels = async () => {
        try {
            setLoading(true);
            
            // Get vendor ID from authenticated user
            const storedUser = localStorage.getItem('studioUser');
            if (!storedUser) {
                toast.error('User not authenticated');
                setLoading(false);
                return;
            }
            
            const user = JSON.parse(storedUser);
            const vendorId = user.vendor_id;
            
            if (!vendorId) {
                toast.error('Vendor ID not found');
                setLoading(false);
                return;
            }
            
            // Fetch seller reels
            const response = await ApiService.getSellerReels(vendorId);
            
            if (response.success) {
                // Group reels by product and calculate counts
                const productMap = {};
                response.data.forEach(reel => {
                    // Extract product IDs from the reel
                    const productIds = reel.product_ids ? reel.product_ids.split(',') : [];
                    
                    // For each product ID, create or update the product group
                    productIds.forEach(productId => {
                        if (!productMap[productId]) {
                            productMap[productId] = {
                                product: `Product ${productId}`, // Will be updated with real product name
                                productId: productId,
                                reelCount: 0,
                                reels: [],
                                title: reel.title,
                                category: reel.category_name || 'N/A',
                                status: reel.status,
                                views: reel.views || 0,
                                likes: reel.likes || 0,
                                date: reel.created_at ? new Date(reel.created_at).toLocaleDateString() : 'N/A'
                            };
                        }
                        productMap[productId].reelCount += 1;
                        productMap[productId].reels.push(reel);
                    });
                });
                
                // Convert to array format for display
                const groupedReels = Object.values(productMap);
                
                // Fetch product names for all products
                if (groupedReels.length > 0) {
                    const productIds = groupedReels.map(item => item.productId);
                    try {
                        const productNamesResponse = await ApiService.getProductNamesByIds(productIds);
                        if (productNamesResponse.success) {
                            // Update product names in the grouped reels
                            groupedReels.forEach(item => {
                                if (productNamesResponse.data[item.productId]) {
                                    item.product = productNamesResponse.data[item.productId];
                                }
                            });
                        }
                    } catch (error) {
                        console.error('Error fetching product names:', error);
                    }
                }
                
                setReels(groupedReels);
            } else {
                toast.error('Failed to load reels: ' + response.message);
            }
        } catch (error) {
            console.error('Error loading reels:', error);
            toast.error('Failed to load reels: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleViewReelVideo = async (productId) => {
        // Navigate to the view page for this product
        navigate(`/studio/seller/reels/${encodeURIComponent(productId)}`);
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                        <Link to="/studio/seller/upload" className="btn btn-success">
                            <i className="ri-add-line me-1"></i> Upload Reel
                        </Link>
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/seller/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Product Name</th>
                                            <th>Reel Count</th>
                                            <th>Title</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((productGroup) => (
                                            <tr key={productGroup.productId}>
                                                <td>{productGroup.product}</td>
                                                <td>{productGroup.reelCount}</td>
                                                <td>{productGroup.title}{productGroup.reelCount > 1 ? ` (+${productGroup.reelCount - 1} more)` : ''}</td>
                                                <td>{productGroup.category || 'N/A'}</td>
                                                <td>{getStatusBadge(productGroup.status)}</td>
                                                <td>{productGroup.views}</td>
                                                <td>{productGroup.likes}</td>
                                                <td>{productGroup.date}</td>
                                                <td>
                                                    <button 
                                                        className="btn btn-sm btn-info"
                                                        onClick={() => handleViewReelVideo(productGroup.productId)}
                                                        title="View Reels"
                                                    >
                                                        <i className="ri-eye-line"></i> View
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
